package validationgen_test

import (
	"bytes"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"

	"tei/internal/codegen/goemit"
	"tei/internal/codegen/goemit/goemittest"
	"tei/internal/core"
	"tei/internal/semantic"
	"tei/internal/sourceindex"
	"tei/internal/workspace"
)

// Different authoring projections of one typed Rule must lower to identical Go
// while retaining different Source identities. This compares actual product
// loaders and the actual generator, not copied canonical structures.
//
// Equivalent generated bytes do not qualify a stale Source reference or
// confer Owner acceptance, runtime authority, or product Builder selection.
func TestSameRuleFromTwoProductSurfacesGeneratesIdenticalGoButDistinctSourceEvidence(t *testing.T) {
	const (
		ruleID          = "sales.order_line.quantity_positive"
		attributeID     = "sales.order_line.quantity"
		markdownPath    = "semantic/sales/order-line-rules.tei.md"
		traditionalPath = "semantic/sales/validation.tei"
	)
	markdownFixture := filepath.Join("..", "..", "workspace", "testdata", "tei-md-rule")
	traditionalFixture := filepath.Join("..", "..", "..", "reference", "workspace", traditionalPath)
	root := t.TempDir()
	markdownRoot := filepath.Join(root, "markdown")
	traditionalRoot := filepath.Join(root, "traditional")

	write := func(destination string, contents []byte) {
		t.Helper()
		if err := os.MkdirAll(filepath.Dir(destination), 0o700); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(destination, contents, 0o600); err != nil {
			t.Fatal(err)
		}
	}
	read := func(path string) []byte {
		t.Helper()
		data, err := os.ReadFile(path)
		if err != nil {
			t.Fatal(err)
		}
		return data
	}
	for _, file := range []string{
		"tei.workspace.yaml",
		"semantic/sales/order.tei",
		markdownPath,
	} {
		write(filepath.Join(markdownRoot, filepath.FromSlash(file)),
			read(filepath.Join(markdownFixture, filepath.FromSlash(file))))
	}
	write(filepath.Join(traditionalRoot, "tei.workspace.yaml"),
		[]byte("workspace: legacy_rule_go_conformance\nformatVersion: 1\nsources:\n  - semantic\n"))
	write(filepath.Join(traditionalRoot, "semantic", "sales", "order.tei"),
		read(filepath.Join(markdownFixture, "semantic", "sales", "order.tei")))
	write(filepath.Join(traditionalRoot, filepath.FromSlash(traditionalPath)), read(traditionalFixture))

	type witness struct {
		rule              semantic.Validation
		code              []byte
		trace             goemit.Trace
		ast               observedPositiveGo
		sourceStart       int
		sourceEnd         int
		index             sourceindex.Index
		sourceFingerprint string
		modelRevision     string
	}
	build := func(workspaceRoot, sourcePath string, expectMarkdown bool) witness {
		t.Helper()
		loaded, err := workspace.Load(workspaceRoot)
		if err != nil {
			t.Fatalf("real Workspace.Load of %s: %v", sourcePath, err)
		}
		if expectMarkdown {
			if len(loaded.AuthoringSources) != 1 ||
				loaded.AuthoringSources[0].Language.LanguageID != "tei.rule-authoring" ||
				loaded.AuthoringSources[0].Language.ContractVersion != "v0" {
				t.Fatalf("unexpected Markdown language selection: %+v", loaded.AuthoringSources)
			}
		} else if len(loaded.AuthoringSources) != 0 {
			t.Fatalf("traditional .tei was not interpreted natively: %+v", loaded.AuthoringSources)
		}

		index, err := workspace.BuildSourceIndexFromLoad(workspaceRoot, loaded)
		if err != nil {
			t.Fatalf("Source Index for same Load: %v", err)
		}
		var rule semantic.Validation
		var attributeType core.CanonicalID
		for _, ns := range loaded.World.Semantics {
			for _, candidate := range ns.Validations {
				if string(candidate.ID) == ruleID {
					if rule.ID != "" {
						t.Fatal("multiple definitions of canonical Rule")
					}
					rule = candidate
				}
			}
			for _, data := range ns.Data {
				for _, attribute := range data.Attributes {
					if string(attribute.ID) == attributeID {
						attributeType = attribute.TypeRef
					}
				}
			}
		}
		if rule.ID != ruleID || rule.Kind != semantic.ValidationPositive ||
			rule.Attribute != attributeID || attributeType != "std.decimal" {
			t.Fatalf("actual selected Rule or Attribute type changed: %+v, %s", rule, attributeType)
		}
		refs := index.ReferencesFor(sourceindex.Subject{Kind: "semantic-validation", ID: ruleID})
		if len(refs) != 1 || refs[0].Role != sourceindex.RoleDefinition ||
			refs[0].ArtifactPath != sourcePath {
			t.Fatalf("Rule identity did not retain its unique authored Source: %+v", refs)
		}
		raw := read(filepath.Join(workspaceRoot, filepath.FromSlash(sourcePath)))
		if err := refs[0].Range.Validate(raw); err != nil {
			t.Fatalf("Source range does not describe current bytes: %v", err)
		}
		start, end := refs[0].Range.Start.Offset, refs[0].Range.End.Offset
		if start < 0 || end <= start || end > len(raw) || string(raw[start:end]) != ruleID {
			t.Fatalf("incorrect Source identity anchor: %+v", refs[0].Range)
		}
		fingerprint := sourceindex.Fingerprint(raw)
		var found bool
		for _, artifact := range index.Artifacts {
			if artifact.Path == sourcePath {
				if artifact.Fingerprint != fingerprint {
					t.Fatal("Source Index used bytes other than the selected original")
				}
				found = true
			}
		}
		if !found {
			t.Fatal("Source Index omitted the selected authoring file")
		}
		goSource, trace, err := tracedPositive(rule, attributeType, "main")
		if err != nil {
			t.Fatalf("generate Go from selected typed Rule: %v", err)
		}
		if _, err := parser.ParseFile(token.NewFileSet(), "generated.go", goSource, parser.AllErrors); err != nil {
			t.Fatalf("generated Go syntax: %v", err)
		}
		if string(trace.Attribute) != attributeID || trace.Check != "CheckQuantityIsPositive" ||
			trace.Parameter != "quantity" ||
			!bytes.Contains(goSource, []byte("quantity.Sign() > 0")) ||
			bytes.Contains(goSource, []byte("validationeval")) {
			t.Fatal("Go generator no longer implements the selected read and decision")
		}
		ast, err := observeGeneratedPositiveGo(goSource, trace)
		if err != nil || ast.BoundAttribute != string(rule.Attribute) || ast.BindingCount != 1 {
			t.Fatalf("selected typed Rule does not match generated Go AST: %+v / %v", ast, err)
		}
		return witness{rule: rule, code: goSource, trace: trace, ast: ast,
			sourceStart: start, sourceEnd: end, index: index,
			sourceFingerprint: fingerprint, modelRevision: sourceindex.ModelRevision(index)}
	}

	markdown := build(markdownRoot, markdownPath, true)
	traditional := build(traditionalRoot, traditionalPath, false)
	if !reflect.DeepEqual(markdown.rule, traditional.rule) {
		t.Fatalf("different authoring syntax changed canonical business meaning: markdown=%+v, traditional=%+v",
			markdown.rule, traditional.rule)
	}
	if !bytes.Equal(markdown.code, traditional.code) ||
		!reflect.DeepEqual(markdown.ast, traditional.ast) {
		t.Fatal("same typed Rule from different Source did not produce equivalent Go and AST")
	}
	// An AST byte span addresses the generated Go, not either authored Rule.
	if markdown.sourceStart >= markdown.sourceEnd ||
		traditional.sourceStart >= traditional.sourceEnd ||
		markdown.ast.BindingStart >= markdown.ast.BindingEnd ||
		markdown.ast.ConditionStart >= markdown.ast.ConditionEnd {
		t.Fatal("authored and generated Go ranges are not independently observable")
	}
	if markdown.sourceFingerprint == traditional.sourceFingerprint ||
		markdown.modelRevision == traditional.modelRevision {
		t.Fatal("different authored Sources lost their separate revision and provenance")
	}

	// A prose-only edit must invalidate the previously observed Source while
	// preserving the typed Rule and generated Go. This is exactly why source
	// Evidence reuse is distinct from compilation/Artifact reuse.
	markdownFile := filepath.Join(markdownRoot, filepath.FromSlash(markdownPath))
	write(markdownFile, append(read(markdownFile), []byte("\n補足説明だけを変更しました。\n")...))
	if err := markdown.index.Validate(func(path string) ([]byte, error) {
		return os.ReadFile(filepath.Join(markdownRoot, filepath.FromSlash(path)))
	}); err == nil || !strings.Contains(err.Error(), "fingerprint is stale") {
		t.Fatalf("stale Source evidence survived prose-only edit: %v", err)
	}
	prose := build(markdownRoot, markdownPath, true)
	if !reflect.DeepEqual(markdown.rule, prose.rule) ||
		!bytes.Equal(markdown.code, prose.code) ||
		!reflect.DeepEqual(markdown.ast, prose.ast) ||
		prose.sourceFingerprint == markdown.sourceFingerprint ||
		prose.modelRevision == markdown.modelRevision {
		t.Fatal("prose-only edit did not separate Source freshness from generated Go semantics")
	}
	if !bytes.Equal(prose.code, traditional.code) {
		t.Fatal("prose-only edit altered equivalence with the traditional authoring surface")
	}

	// A generated-code mutation can preserve the same syntactic shape while
	// binding to a *different* Attribute. The binding is the Trace, so the
	// mutant is a Trace that names another Attribute for the same check
	// function. The authored Rule must not silently inherit that new read
	// target just because the Go parser accepts the file.
	readMutant := markdown.trace
	readMutant.Attribute = "sales.order_line.discount"
	observedMutant, err := observeGeneratedPositiveGo(markdown.code, readMutant)
	if err != nil {
		t.Fatalf("read-target mutant should remain structurally observable: %v", err)
	}
	if observedMutant.BoundAttribute == string(markdown.rule.Attribute) {
		t.Fatal("mutant generated Go was incorrectly bound to its original authored Rule")
	}
	// A comment that names another attribute is not a new read target:
	// every comment is replaced with one claiming discount, whatever the
	// generator's wording, and the observed binding does not move.
	rewritten, err := goemittest.RewriteComments(goemit.Output{
		Files: []goemit.File{{Path: markdown.trace.File, Content: markdown.code}},
	}, func(string, string) string {
		return "quantity reads attribute sales.order_line.discount"
	})
	if err != nil {
		t.Fatal(err)
	}
	commentMutant := rewritten.File(markdown.trace.File)
	if bytes.Equal(commentMutant, markdown.code) {
		t.Fatal("comment mutant was not applied")
	}
	observedComment, err := observeGeneratedPositiveGo(commentMutant, markdown.trace)
	if err != nil || observedComment.BoundAttribute != string(markdown.rule.Attribute) {
		t.Fatalf("a comment edit changed the observed binding: %+v %v", observedComment, err)
	}
	thresholdMutant := bytes.Replace(markdown.code, []byte("quantity.Sign() > 0"),
		[]byte("quantity.Sign() >= 0"), 1)
	if bytes.Equal(thresholdMutant, markdown.code) {
		t.Fatal("threshold mutant was not applied")
	}
	if _, err := observeGeneratedPositiveGo(thresholdMutant, markdown.trace); err == nil {
		t.Fatal("non-strict threshold was accepted as the original positive Rule")
	}
}
